/**
 * L1 Automated Triage — Browser (UX) Canary.
 *
 * A CloudWatch Synthetics Puppeteer canary that complements the API health
 * canary by exercising the real browser experience:
 *
 *   1. Loads the target page in a headless browser (following redirects
 *      naturally, as a browser does).
 *   2. Measures page-load timing (navigation duration).
 *   3. Verifies that a configured key UI element is present, catching
 *      browser-only failures (broken/missing UI, rendering errors) that a raw
 *      HTTP check cannot see.
 *
 * A failure here drives an `l1t-health-` prefixed availability alarm, so
 * UX/page-load problems enter the same routing → DevOps Agent triage flow.
 *
 * Configuration (environment variables set by the construct):
 *   L1T_UX_URL_PARAMETER_NAME   SSM parameter holding the page URL
 *   L1T_UX_URL                  inline page URL (takes precedence)
 *   L1T_UX_KEY_SELECTOR         CSS selector of a key element to verify (default: body)
 *   L1T_UX_MAX_LOAD_MS          soft page-load budget in ms (logged; default 10000)
 */

'use strict';

const synthetics = require('Synthetics');
const log = require('SyntheticsLogger');

async function resolveUrl() {
    const inline = process.env.L1T_UX_URL;
    if (inline && inline.trim().length > 0) {
        return inline.trim();
    }
    const paramName = process.env.L1T_UX_URL_PARAMETER_NAME;
    if (!paramName) {
        throw new Error('No UX target URL configured (set L1T_UX_URL or L1T_UX_URL_PARAMETER_NAME)');
    }
    const { SSMClient, GetParameterCommand } = require('@aws-sdk/client-ssm');
    const ssm = new SSMClient({});
    const res = await ssm.send(new GetParameterCommand({ Name: paramName, WithDecryption: false }));
    if (!res.Parameter || !res.Parameter.Value) {
        throw new Error(`SSM parameter ${paramName} has no value`);
    }
    return res.Parameter.Value;
}

const pageLoadBlueprint = async function () {
    const url = await resolveUrl();
    const keySelector = process.env.L1T_UX_KEY_SELECTOR || 'body';
    const maxLoadMs = Number(process.env.L1T_UX_MAX_LOAD_MS) || 10000;

    const page = await synthetics.getPage();

    const startedAt = Date.now();
    await synthetics.executeStep('load_page', async function () {
        const response = await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 30000 });
        const status = response ? response.status() : null;
        const loadMs = Date.now() - startedAt;
        log.info(
            JSON.stringify({
                l1tUxCheck: true,
                url,
                finalUrl: page.url(),
                status,
                loadMs,
                withinBudget: loadMs <= maxLoadMs,
                timestamp: new Date().toISOString(),
            }),
        );
    });

    await synthetics.executeStep('verify_ui_element', async function () {
        // Throws (failing the canary) if the key element is not present.
        await page.waitForSelector(keySelector, { timeout: 10000 });
        log.info(JSON.stringify({ l1tUxCheck: true, url, keySelector, elementPresent: true }));
    });

    await synthetics.takeScreenshot('ux_loaded', 'loaded');
};

exports.handler = async () => {
    return await pageLoadBlueprint();
};
